Implement the features for {{appName}}.

**Features to implement**: {{features}}

**For each feature**:

1. **Create data types** (`src/types/{feature}.types.ts`)
2. **Create API service** (`src/services/{feature}.service.ts`)
3. **Create custom hooks** (`src/hooks/api/use{Feature}.ts`)
4. **Create components**:
   - Container (logic)
   - View (presentation)
   - Form (if CRUD)
5. **Create page** (`src/pages/{Feature}Page/`)
6. **Add route** (update `src/routes/index.tsx`)
7. **Write tests**

**Example: CRUD Feature**

### 1. Types (`src/types/tasks.types.ts`)
```typescript
export interface Task {
  id: string;
  title: string;
  description: string;
  completed: boolean;
  createdAt: Date;
  updatedAt: Date;
}

export interface CreateTaskRequest {
  title: string;
  description: string;
}

export interface UpdateTaskRequest {
  id: string;
  title?: string;
  description?: string;
  completed?: boolean;
}
```

### 2. API Service (`src/services/tasks.service.ts`)
```typescript
import { apiClient } from './api';
import type { Task, CreateTaskRequest, UpdateTaskRequest } from '@types/tasks.types';

export const tasksService = {
  async getAll(): Promise<Task[]> {
    const { data } = await apiClient.get<Task[]>('/tasks');
    return data;
  },

  async getById(id: string): Promise<Task> {
    const { data } = await apiClient.get<Task>(`/tasks/${id}`);
    return data;
  },

  async create(task: CreateTaskRequest): Promise<Task> {
    const { data } = await apiClient.post<Task>('/tasks', task);
    return data;
  },

  async update(task: UpdateTaskRequest): Promise<Task> {
    const { data } = await apiClient.put<Task>(`/tasks/${task.id}`, task);
    return data;
  },

  async delete(id: string): Promise<void> {
    await apiClient.delete(`/tasks/${id}`);
  },
};
```

### 3. React Query Hook (`src/hooks/api/useTasks.ts`)
```typescript
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { tasksService } from '@/services/tasks.service';
import type { CreateTaskRequest, UpdateTaskRequest } from '@types/tasks.types';

const TASKS_KEY = ['tasks'];

export function useTasks() {
  return useQuery({
    queryKey: TASKS_KEY,
    queryFn: tasksService.getAll,
  });
}

export function useTask(id: string) {
  return useQuery({
    queryKey: [...TASKS_KEY, id],
    queryFn: () => tasksService.getById(id),
    enabled: !!id,
  });
}

export function useCreateTask() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: tasksService.create,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: TASKS_KEY });
    },
  });
}

export function useUpdateTask() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: tasksService.update,
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: TASKS_KEY });
      queryClient.invalidateQueries({ queryKey: [...TASKS_KEY, data.id] });
    },
  });
}

export function useDeleteTask() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: tasksService.delete,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: TASKS_KEY });
    },
  });
}
```

### 4. Page Component (`src/pages/TasksPage/TasksPage.tsx`)
```typescript
import { useTasks, useCreateTask } from '@hooks/api/useTasks';
import { TaskList } from '@components/features/tasks/TaskList';
import { TaskForm } from '@components/features/tasks/TaskForm';
import { LoadingSpinner } from '@components/common/LoadingSpinner';
import { ErrorMessage } from '@components/common/ErrorMessage';
import type { CreateTaskRequest } from '@types/tasks.types';

export function TasksPage() {
  const { data: tasks, isLoading, error } = useTasks();
  const createTask = useCreateTask();

  const handleCreateTask = async (taskData: CreateTaskRequest) => {
    await createTask.mutateAsync(taskData);
  };

  if (isLoading) return <LoadingSpinner />;
  if (error) return <ErrorMessage message={error.message} />;

  return (
    <div>
      <h1>Tasks</h1>
      <TaskForm onSubmit={handleCreateTask} />
      <TaskList tasks={tasks || []} />
    </div>
  );
}
```

