Set up testing infrastructure for {{appName}}.

**Test Types**:

### 1. Unit Tests (Components)

**Setup MSW** (`src/mocks/handlers.ts`):
```typescript
import { http, HttpResponse } from 'msw';
import type { Task } from '@types/tasks.types';

const mockTasks: Task[] = [
  { id: '1', title: 'Test Task', description: 'Description', completed: false, createdAt: new Date(), updatedAt: new Date() },
];

export const handlers = [
  http.get('/api/tasks', () => {
    return HttpResponse.json(mockTasks);
  }),

  http.post('/api/tasks', async ({ request }) => {
    const newTask = await request.json();
    return HttpResponse.json({ id: '2', ...newTask });
  }),
];
```

**Test Setup** (`src/test/setup.ts`):
```typescript
import '@testing-library/jest-dom';
import { setupServer } from 'msw/node';
import { handlers } from '@/mocks/handlers';

export const server = setupServer(...handlers);

beforeAll(() => server.listen());
afterEach(() => server.resetHandlers());
afterAll(() => server.close());
```

### 2. E2E Tests (Playwright)

**Playwright Config** (`playwright.config.ts`):
```typescript
import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
  testDir: './tests/e2e',
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  workers: process.env.CI ? 1 : undefined,
  reporter: 'html',
  use: {
    baseURL: 'http://localhost:3000',
    trace: 'on-first-retry',
  },
  projects: [
    { name: 'chromium', use: { ...devices['Desktop Chrome'] } },
  ],
  webServer: {
    command: 'npm run dev',
    url: 'http://localhost:3000',
    reuseExistingServer: !process.env.CI,
  },
});
```

**E2E Test Example** (`tests/e2e/tasks.spec.ts`):
```typescript
import { test, expect } from '@playwright/test';

test.describe('Tasks Feature', () => {
  test('should create a new task', async ({ page }) => {
    await page.goto('/');

    await page.fill('input[name="title"]', 'New Task');
    await page.fill('textarea[name="description"]', 'Task description');
    await page.click('button[type="submit"]');

    await expect(page.locator('text=New Task')).toBeVisible();
  });

  test('should complete a task', async ({ page }) => {
    await page.goto('/');

    const task = page.locator('[data-testid="task-1"]');
    await task.locator('input[type="checkbox"]').check();

    await expect(task).toHaveAttribute('data-completed', 'true');
  });
});
```

**Set up comprehensive testing**.
